import React, { useState, useMemo } from "react";
import "../styles/SkinAnalyzer.css";

export default function SkinAnalyzer() {
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [recommendations, setRecommendations] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingRec, setLoadingRec] = useState(false);

  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setPhoto(file);
      const reader = new FileReader();
      reader.onloadend = () => setPhotoPreview(reader.result);
      reader.readAsDataURL(file);
    }
  };

  const analyzeSkin = async () => {
    if (!photo) return alert("Загрузите фото!");
    setLoading(true);
    setAnalysis(null);
    setRecommendations("");

    const formData = new FormData();
    formData.append("photo", photo);

    try {
      const res = await fetch("http://localhost:4000/api/skin/analyze", {
        method: "POST",
        credentials: "include",
        body: formData,
      });
      const data = await res.json();
      setAnalysis(data);
    } catch (err) {
      console.error(err);
      alert("Ошибка анализа кожи");
    } finally {
      setLoading(false);
    }
  };

  const getRecommendations = async () => {
    if (!analysis) return alert("Сначала сделайте анализ!");
    setLoadingRec(true);

    try {
      const res = await fetch("http://localhost:4000/api/skin/recommend", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ skinAnalysis: analysis }),
      });
      const data = await res.json();
      setRecommendations(data.recommendations);
    } catch (err) {
      console.error(err);
      alert("Ошибка получения рекомендаций");
    } finally {
      setLoadingRec(false);
    }
  };

  const getPercentageColor = (percent) => {
    const num = parseFloat(percent);
    if (num > 70) return "var(--danger)";
    if (num > 40) return "var(--warning)";
    return "var(--success)";
  };

  // useMemo для кэширования форматированного анализа
  const formattedAnalysis = useMemo(() => {
    if (!analysis) return [];
    if (analysis.analysis?.formatted) {
      return analysis.analysis.formatted.map((item) => ({
        ...item,
        displayPercentage: item.percentage || (item.value * 100).toFixed(1),
        color:
          item.value > 0.7 ? "var(--danger)" :
          item.value > 0.4 ? "var(--warning)" :
          "var(--success)",
      }));
    }
    // Старый формат
    if (analysis.formatted) {
      return analysis.formatted
        .split("\n")
        .map((line) => {
          const match = line.match(/(.+?) — (\d+\.?\d*)%/);
          if (!match) return null;
          const [, name, percent] = match;
          return { name: name.trim(), displayPercentage: percent, color: getPercentageColor(percent) };
        })
        .filter(Boolean);
    }
    return [];
  }, [analysis]);

  return (
    <div className="skin-analyzer">
      <h2 className="title">🧬 Анализ кожи</h2>

      {/* Загрузка фото */}
      <div className="upload-section">
        <input type="file" accept="image/*" onChange={handlePhotoChange} />
        {photo && <span>{photo.name}</span>}
        {photoPreview && <img src={photoPreview} alt="Предпросмотр" className="photo-preview" />}
        <button onClick={analyzeSkin} disabled={loading || !photo}>
          {loading ? "Анализируем..." : "🔍 Анализировать кожу"}
        </button>
      </div>

      {/* Результаты анализа */}
      {formattedAnalysis.length > 0 && (
        <div className="results-section">
          <h3>📊 Результат анализа</h3>
          <div className="analysis-grid">
            {formattedAnalysis.map((item, index) => (
              <div key={index} className="analysis-item">
                <span>{item.name}</span>
                <div className="progress-bar">
                  <div
                    className="progress-fill"
                    style={{ width: `${item.displayPercentage}%`, backgroundColor: item.color }}
                  />
                </div>
                <span>{item.displayPercentage}%</span>
              </div>
            ))}
          </div>
          <button onClick={getRecommendations} disabled={loadingRec}>
            {loadingRec ? "Генерируем рекомендации..." : "💡 Получить рекомендации"}
          </button>
        </div>
      )}

      {/* Рекомендации */}
      {recommendations && (
        <div className="recommendations-section">
          <h3>🌟 Рекомендации по уходу</h3>
          {recommendations.split("\n").map((line, i) => (
            <p key={i}>{line}</p>
          ))}
        </div>
      )}
    </div>
  );
}
